<?php
function repack_ready(){return packaging_ready()&&setting('repackaging_batch_version','')==='5.3.4';}
function repack_require(){if(!repack_ready())throw new Exception('Run the Repackaging Batch upgrade first.');}
function migrate_repackaging(){migrate_packaging();db()->exec("CREATE TABLE IF NOT EXISTS repackaging_batches(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_ref VARCHAR(100) NOT NULL UNIQUE,claim_key CHAR(64) NOT NULL UNIQUE,txn_date DATE NOT NULL,source_name VARCHAR(100) NOT NULL,reference_no VARCHAR(100) NOT NULL,owner_id INT NOT NULL,due_date DATE NULL,reason TEXT NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'Review',rows_json LONGTEXT NOT NULL,review_digest CHAR(64) NOT NULL,created_by INT NOT NULL,posted_by INT NULL,posted_at DATETIME NULL,reversed_by_request BIGINT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");db()->exec("CREATE TABLE IF NOT EXISTS repackaging_batch_lines(id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT NOT NULL,line_no INT NOT NULL,product_id INT NOT NULL,qty INT NOT NULL,source_id BIGINT NULL,target_id BIGINT NOT NULL,release_id BIGINT NULL,baseline_released INT NOT NULL DEFAULT 0,mode VARCHAR(30) NOT NULL,allocation_json LONGTEXT NOT NULL,UNIQUE(batch_id,line_no),INDEX(source_id),INDEX(target_id)) ENGINE=InnoDB");global $CFG;$q=db()->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME='repackaging_batch_lines' AND COLUMN_NAME='baseline_released'");$q->execute([$CFG['db_name']]);if(!$q->fetchColumn())db()->exec('ALTER TABLE repackaging_batch_lines ADD COLUMN baseline_released INT NOT NULL DEFAULT 0');set_setting('repackaging_batch_version','5.3.4');}
function repack_access(){repack_require();if(!can_action('repack_stage'))throw new Exception('Inventory Controller or Admin access required.');}
function repack_batch($id,$lock=false){repack_require();$q=db()->prepare('SELECT * FROM repackaging_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([(int)$id]);$b=$q->fetch();if(!$b)throw new Exception('Repackaging batch not found.');return $b;}
function repack_active_source($id){$q=db()->prepare("SELECT l.batch_id FROM repackaging_batch_lines l JOIN repackaging_batches b ON b.id=l.batch_id JOIN non_sellable n ON n.id=l.target_id WHERE l.source_id=? AND b.status='Posted' AND n.reversed_by_request IS NULL AND n.qty>COALESCE((SELECT SUM(k.qty) FROM nonsellable_release_links k WHERE k.non_sellable_id=n.id),0) LIMIT 1");$q->execute([$id]);return (int)$q->fetchColumn();}
function repack_analysis($b){
 repack_require();$rows=is_string($b['rows_json']??null)?json_decode($b['rows_json'],true):($b['rows']??[]);if(!is_array($rows)||!count($rows)||count($rows)>100)throw new Exception('Enter 1 to 100 product lines.');$date=process_date($b['txn_date']);$seen=[];$stocks=[];$plan=[];$snap=[];
 foreach($rows as $i=>$line){$key=(string)($line['source']??'');if(isset($seen[$key]))throw new Exception('A source is repeated. Combine its quantity into one line.');$seen[$key]=true;$qty=whole_number($line['qty']??'','Line quantity',1);$source=null;$mode='';$nsid=null;$baseline=0;
  if(preg_match('/^NS:([1-9][0-9]*)$/D',$key,$m)){$nsid=(int)$m[1];$q=db()->prepare('SELECT n.*,p.name,p.master_sku,p.active FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.id=?');$q->execute([$nsid]);$source=$q->fetch();if(!$source||!$source['active']||$source['reversed_by_request']!==null||(int)$source['qty']<=0)throw new Exception('Restricted source is unavailable.');if($date<$source['txn_date'])throw new Exception('Batch date cannot precede its source transaction.');$baseline=release_total($nsid);$remaining=max(0,(int)$source['qty']-$baseline);if($qty>$remaining)throw new Exception('Quantity exceeds the remaining source record.');if(repack_active_source($nsid))throw new Exception('This source already belongs to an active repackaging batch. Open that batch.');$mode=packaging_condition($source['condition_type'])?'Group Existing':'Restricted Reclassification';if($mode==='Group Existing'&&$qty!==$remaining)throw new Exception('For an existing packaging source, group its full remaining quantity. Partial Ready for Sale is available afterward.');$pid=(int)$source['product_id'];$snap[]=['source'=>$source,'remaining'=>$remaining];
  }elseif(preg_match('/^ST:([1-9][0-9]*)$/D',$key,$m)){$pid=(int)$m[1];$p=active_product($pid);$q=db()->prepare('SELECT name,master_sku FROM products WHERE id=?');$q->execute([$pid]);$source=$q->fetch();$mode='Sellable Reclassification';}else throw new Exception('Select an existing stock source for every line.');
  if(!isset($stocks[$pid])){check_platform_alignment($pid);$s=stock_row($pid);$alloc=[];foreach(['Shopee','Lazada','TikTok'] as $pl)$alloc[$pl]=platform_qty($pl,$pid);$stocks[$pid]=['sellable'=>$s['current'],'restricted'=>$s['nonsellable'],'available'=>$alloc];$snap[]=['pid'=>$pid,'stock'=>$s,'platforms'=>$alloc];}
  $allocation=['Shopee'=>0,'Lazada'=>0,'TikTok'=>0];if($mode==='Sellable Reclassification'){if($qty>$stocks[$pid]['sellable'])throw new Exception('Insufficient sellable stock for planned repackaging.');$left=$qty;$platforms=$stocks[$pid]['available'];arsort($platforms,SORT_NUMERIC);foreach($platforms as $pl=>$available){$take=min($left,max(0,$available));$allocation[$pl]=$take;$stocks[$pid]['available'][$pl]-=$take;$left-=$take;}if($left)throw new Exception('Insufficient positive platform allocation; reconcile the stock first.');$stocks[$pid]['sellable']-=$qty;
  }else{if($qty>$stocks[$pid]['restricted'])throw new Exception('Insufficient total restricted stock; review legacy releases.');$stocks[$pid]['restricted']-=$qty;}
  $plan[]=['line'=>$i+1,'source'=>$key,'source_id'=>$nsid,'product_id'=>$pid,'name'=>$source['name'],'master_sku'=>$source['master_sku'],'source_ref'=>$source['order_id']??'Existing sellable stock','old_condition'=>$source['condition_type']??'Sellable','qty'=>$qty,'mode'=>$mode,'baseline_released'=>$mode==='Group Existing'?$baseline:0,'allocation'=>$allocation];
 }
 $digest=hash('sha256',json_encode([$b['txn_date'],$b['source_name'],$b['reference_no'],$b['owner_id'],$b['due_date'],$b['reason'],$plan,$snap]));return ['lines'=>$plan,'digest'=>$digest];
}
function repack_stage($input){repack_access();return process_transaction(function()use($input){$date=process_date($input['txn_date']??'');require_open_inventory_date($date);$owner=packaging_owner($input['owner_id']??0);$due=packaging_due($input['due_date']??'',$date);$reason=process_reason($input['reason']??'');$source=trim($input['source_name']??'');$ref=trim($input['reference_no']??'');if(!in_array($source,['Returns','Existing Warehouse Stock','RAW / For Packaging','Other Restricted Stocks'],true)||$ref===''||strlen($ref)>100)throw new Exception('Choose the source and enter an existing reference or unique internal batch reference.');$token=(string)($input['batch_ref']??'');if(!preg_match('/^RP-[A-Za-z0-9_-]{8,90}$/D',$token))throw new Exception('Invalid form reference. Refresh the form.');$key=hash('sha256',json_encode([norm($source),norm($ref)]));$q=db()->prepare('SELECT id FROM repackaging_batches WHERE claim_key=? OR batch_ref=?');$q->execute([$key,$token]);if($q->fetchColumn())throw new Exception('This source/reference or form is already recorded. Open its batch history.');$b=['txn_date'=>$date,'source_name'=>$source,'reference_no'=>$ref,'owner_id'=>$owner,'due_date'=>$due,'reason'=>$reason,'rows'=>$input['lines']??[]];$a=repack_analysis($b);$rows=array_map(fn($l)=>['source'=>$l['source'],'qty'=>$l['qty']],$a['lines']);db()->prepare('INSERT INTO repackaging_batches(batch_ref,claim_key,txn_date,source_name,reference_no,owner_id,due_date,reason,rows_json,review_digest,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$token,$key,$date,$source,$ref,$owner,$due,$reason,json_encode($rows),$a['digest'],current_user()['id']]);$id=(int)db()->lastInsertId();audit('Review repackaging batch','Repackaging',$token,count($rows).' lines; existing stocks only; no inventory changed.');return $id;});}
function repack_refresh($id){repack_access();return process_transaction(function()use($id){$b=repack_batch($id,true);if($b['status']!=='Review')throw new Exception('Only a review batch can be refreshed.');$a=repack_analysis($b);db()->prepare('UPDATE repackaging_batches SET review_digest=? WHERE id=?')->execute([$a['digest'],$id]);audit('Refresh repackaging review','Repackaging',$b['batch_ref'],'Stock snapshot refreshed; no inventory changed.');});}
function repack_cancel($id){repack_access();return process_transaction(function()use($id){$b=repack_batch($id,true);if($b['status']!=='Review')throw new Exception('Only an unposted review can be cancelled.');db()->prepare("UPDATE repackaging_batches SET status='Cancelled' WHERE id=?")->execute([$id]);audit('Cancel repackaging batch','Repackaging',$b['batch_ref'],'No inventory changed. Reference remains in history.');});}
function repack_post($id,$digest,$ack){repack_access();if(!$ack)throw new Exception('Review and acknowledge the existing-stock reclassification.');return process_transaction(function()use($id,$digest){$b=repack_batch($id,true);if($b['status']!=='Review')throw new Exception('This batch is already posted or cancelled.');require_open_inventory_date($b['txn_date']);$a=repack_analysis($b);$pids=array_values(array_unique(array_column($a['lines'],'product_id')));sort($pids);foreach($pids as $pid)db()->prepare('SELECT id FROM products WHERE id=? FOR UPDATE')->execute([$pid]);$ids=array_filter(array_column($a['lines'],'source_id'));sort($ids);foreach($ids as $ns)db()->prepare('SELECT id FROM non_sellable WHERE id=? FOR UPDATE')->execute([$ns]);$a=repack_analysis($b);if(!hash_equals($b['review_digest'],$a['digest'])||!hash_equals($a['digest'],(string)$digest))throw new Exception('Stocks or source records changed. Refresh Review and inspect the updated lines before submitting.');$before=[];foreach($pids as $pid)$before[$pid]=stock_row($pid)['physical'];
 foreach($a['lines'] as $l){$pid=$l['product_id'];$qty=$l['qty'];$release=null;$target=$l['source_id'];$note=$b['batch_ref'].'; '.$b['source_name'].'; '.$b['reference_no'].'; '.$b['reason'];
  if($l['mode']!=='Group Existing'){
   if($l['mode']==='Restricted Reclassification'){db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$b['txn_date'],$pid,$qty,'Repackaging Reclassification',$b['batch_ref'],$note,current_user()['id']]);$release=(int)db()->lastInsertId();db()->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$release,$l['source_id'],$qty]);}
   db()->prepare("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id,packaging_owner_id,packaging_due_date,packaging_state,packaging_source) VALUES(?,NULL,?,?,?,'For Repackaging','For Repack','Pending','Repackaging Batch',?,?,?,?,?,'Pending',?)")->execute([$b['txn_date'],$b['batch_ref'],$pid,$qty,$l['mode']==='Sellable Reclassification'?1:0,$note,current_user()['id'],$b['owner_id'],$b['due_date'],$b['source_name'].' / '.$b['reference_no']]);$target=(int)db()->lastInsertId();foreach($l['allocation'] as $pl=>$n)if($n)change_platform_stock($pl,$pid,-$n,$b['batch_ref'],$b['txn_date']);
  }else{db()->prepare('UPDATE non_sellable SET packaging_owner_id=?,packaging_due_date=? WHERE id=?')->execute([$b['owner_id'],$b['due_date'],$target]);}
  db()->prepare('INSERT INTO repackaging_batch_lines(batch_id,line_no,product_id,qty,source_id,target_id,release_id,baseline_released,mode,allocation_json) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$id,$l['line'],$pid,$qty,$l['source_id'],$target,$release,$l['baseline_released'],$l['mode'],json_encode($l['allocation'])]);
 }
 foreach($pids as $pid){check_platform_alignment($pid);if(stock_row($pid)['physical']!==$before[$pid])throw new Exception('Physical stock changed unexpectedly. The whole batch was rolled back.');}db()->prepare("UPDATE repackaging_batches SET status='Posted',posted_by=?,posted_at=NOW() WHERE id=?")->execute([current_user()['id'],$id]);audit('Post repackaging batch','Repackaging',$b['batch_ref'],count($a['lines']).' lines; same SKUs; physical total unchanged.');return $id;});}
function repack_reversal_plan($id,$plan){repack_require();$b=repack_batch($id);if($b['status']!=='Posted')throw new Exception('Select a posted repackaging batch.');$q=db()->prepare('SELECT * FROM repackaging_batch_lines WHERE batch_id=? ORDER BY line_no');$q->execute([$id]);$lines=$q->fetchAll();foreach($lines as $l){if(release_total($l['target_id'])>(int)$l['baseline_released'])throw new Exception('A batch item was completed or released. Reverse its linked completion/release first.');if($l['mode']==='Group Existing')continue;$q=db()->prepare('SELECT * FROM non_sellable WHERE id=? AND reversed_by_request IS NULL');$q->execute([$l['target_id']]);$n=$q->fetch();if(!$n)throw new Exception('Batch target changed.');$plan['non_sellable'][]=$n;foreach(json_decode($l['allocation_json'],true) as $pl=>$qty)if($qty)$plan['platforms'][]=['pid'=>(int)$l['product_id'],'platform'=>$pl,'delta'=>(int)$qty];if($l['release_id']){$q=db()->prepare('SELECT * FROM nonsellable_outflows WHERE id=? AND reversed_by_request IS NULL');$q->execute([$l['release_id']]);$o=$q->fetch();if(!$o)throw new Exception('Batch reclassification link changed.');$plan['nonsellable_outflows'][]=$o;$q=db()->prepare('SELECT * FROM nonsellable_release_links WHERE release_id=?');$q->execute([$l['release_id']]);foreach($q as $k)$plan['release_links'][]=$k;}}$plan['reference']=$b['batch_ref'];$plan['repack_batch']=$b;$plan['repack_lines']=$lines;return $plan;}
